#include <WiFi.h>
const char* SSID = "{{ssid}}";
const char* PASS = "{{password}}";

void setup() {
  Serial.begin(115200);
  WiFi.mode(WIFI_STA);
  WiFi.begin(SSID, PASS);
  while (WiFi.status() != WL_CONNECTED) { delay(500); Serial.print('.'); }
  Serial.println();
  Serial.print("IP="); Serial.println(WiFi.localIP());
}

void loop() {}
